const august17Editorial = {
  'filipino-customer-support-quality-coordinator': [
    ['Sample the queue, not the story', ['Choose a fixed set of replies and keep the customer question beside each one. A reviewer can then check whether the answer followed the approved support guidance.', 'A sample should include a reply that passed, one that needs a small correction, and one whose policy reference is unclear. Those cases teach the lane more than a single perfect example.']],
    ['Turn corrections into coaching notes', ['Write the correction against the reply, not against the person. Name the missing step, the approved reference, and the next review date.', 'If several replies miss the same point, send the pattern to the support owner. The coordinator records the signal; the owner decides whether guidance or training should change.']],
    ['Keep customer context intact', ['Do not trim away the earlier messages when preparing a quality sample. Tone, promised next steps, and the customer request often depend on that context.', 'Separate an observable issue from an interpretation. “The reply omitted the return window” can be checked; “the agent did not care” cannot.']],
    ['Escalate policy ambiguity', ['A quality lane should stop when two approved references disagree or a reply would create a new commitment. Preserve both links and state the question plainly.', 'The support lead owns the answer. Once resolved, add the decision to the review notes so the next sample does not reopen the same uncertainty.']],
    ['Use a coaching-ready handoff', ['Send the owner a dated sample, the relevant rule, the correction, and the proposed coaching point. Avoid a score without evidence.', 'The lane is ready to grow when another reviewer can reproduce the finding from the same record and reach the same boundary.']],
  ],
  'filipino-business-process-mapping-assistant': [
    ['Interview for sequence, not slogans', ['Ask what starts the work, what information arrives, what the person checks, and what they hand to the next person. Record the observed sequence before suggesting a better one.', 'Capture ordinary work and the exception that causes a pause. A map that shows only the happy path hides the work a process owner most needs to see.']],
    ['Mark observation separately', ['Use a visual distinction for current practice, owner-approved rule, and proposed improvement. That prevents a draft map from quietly becoming a new policy.', 'Name the source of each step, such as an interview, work instruction, or system record. If no source supports a step, label it as a question.']],
    ['Show systems and handoffs', ['Include the screen, file, or queue where a step happens and the person who receives the result. The handoff is often where missing information appears.', 'Do not infer that a system update means the work is complete. Ask what the receiving owner checks before accepting it.']],
    ['Handle competing versions', ['When two staff members describe the process differently, keep both accounts in the working notes. Do not select the cleaner version without the owner.', 'A short discrepancy log gives the process owner a useful agenda: which step varies, why it varies, and which rule should govern it.']],
    ['Release a map that can be tested', ['Give the owner a map, source notes, open questions, and one walkthrough example. Invite someone who did not provide the interview to follow it.', 'Revise only after the owner confirms the current-state boundary. Improvements belong in a separate proposal so the record stays honest.']],
  ],
  'filipino-document-intake-specialist': [
    ['Define what a complete packet means', ['List the file types, required fields, naming pattern, and source details that make an intake item ready for review. Keep the original submission unchanged.', 'Show the sender one complete packet and one example with a single missing item. A clear rejection reason is kinder than a vague request to resend everything.']],
    ['Protect originals at the first touch', ['Store the submitted file in its approved location before renaming or routing anything. Record the received time and the source reference.', 'If a file arrives through an unexpected channel or contains sensitive material, pause the intake and use the owner’s escalation route.']],
    ['Make missing information visible', ['Use reason codes that identify the absent page, field, or approval. Avoid editing the record to make it look complete.', 'A queue owner should be able to tell whether an item is waiting on the sender, an internal reviewer, or a decision. Those are different next actions.']],
    ['Route ambiguity without guessing', ['Unreadable pages, conflicting identifiers, and unclear authority need a question, not a creative fix. Keep the evidence attached to the question.', 'The specialist can point out the conflict and suggest what is missing. The document owner decides which source controls.']],
    ['Review the queue by failure type', ['At the end of a cycle, group returns by reason rather than blaming individual senders. Repeated missing fields may indicate a form or instruction problem.', 'Expand the lane only when the acceptance checklist works for new documents and exceptions still reach a named reviewer.']],
  ],
  'filipino-customer-renewal-preparation-coordinator': [
    ['Build the renewal packet from dated facts', ['Collect usage notes, open actions, agreement dates, and prior commitments with their source and last-updated date. Do not fill a gap with an assumption.', 'Put unresolved items in their own section. A renewal owner should see what is known before discussing what might happen next.']],
    ['Separate evidence from a forecast', ['A missed action is a fact; a prediction about retention is a decision owner’s interpretation. Keep those lines separate in the packet.', 'Use neutral labels such as confirmed, awaiting customer, and owner question. They are more useful than a premature health score.']],
    ['Respect agreement boundaries', ['Copy the relevant date or clause reference without rewriting contract language. Route any question about terms to the authorized account or legal owner.', 'The coordinator can flag a notice window or missing document. They should not promise an amendment, concession, or renewal outcome.']],
    ['Prepare the meeting around questions', ['Arrange the packet so the owner can answer three practical questions: what changed, what remains open, and what requires a decision.', 'Timestamp account notes and identify the person responsible for each follow-up. A meeting list without ownership becomes another unresolved queue.']],
    ['Close the loop after review', ['Record the owner’s approved next steps and keep discarded assumptions out of the final account record. Preserve the source notes for later reference.', 'The lane is ready for more accounts when a second coordinator can assemble the same evidence without relying on private memory.']],
  ],
  'filipino-accounts-payable-exception-coordinator': [
    ['Catch exceptions before payment action', ['Build the queue from duplicate flags, missing approvals, amount mismatches, and unclear supplier details. Link each item to the invoice and the source that raised the concern.', 'Do not edit the invoice to remove the reason it entered review. The exception record should explain what needs a finance decision.']],
    ['Use reason codes that travel', ['A good code tells the reviewer whether the issue is duplication, missing evidence, a purchase-order mismatch, or an unclear owner. Keep notes short but specific.', 'If the same invoice is being chased in two places, join the follow-up rather than creating a second record.']],
    ['Keep payment authority with finance', ['The coordinator can request a document, compare fields, and report what differs. They cannot approve an invoice, override a control, or release a payment.', 'Write that boundary in the queue instructions. It protects both the business and the person doing the preparation.']],
    ['Make supplier questions precise', ['Ask for the exact missing document or clarification, and preserve the original invoice while waiting. Avoid wording that implies payment is guaranteed.', 'Escalate tax, banking, duplicate-payment, and policy questions to the finance owner with the evidence attached.']],
    ['Review aging by cause', ['Sort open exceptions by reason and age. That shows whether the bottleneck is a missing supplier record, an internal approval, or a disputed amount.', 'A small, categorized queue is a better launch target than a promise to process every invoice regardless of evidence.']],
  ],
  'filipino-website-accessibility-review-assistant': [
    ['Start with an observable checklist', ['Define the page, element, check, and evidence required for each review item. A heading-level finding should identify the page and the heading text.', 'Keep the checklist narrow enough that two reviewers can record the same observation. Do not present a checklist result as a complete legal determination.']],
    ['Record the user-facing problem', ['Describe what a visitor encounters, such as a link with no useful name or a form label that does not identify its field. Include a screenshot or page reference where approved.', 'Avoid prescribing a code change when the role only records findings. The web owner can choose the fix after reviewing the evidence.']],
    ['Handle contrast and interaction carefully', ['A color flag needs the affected text or control, its page, and the measurement method used by the approved tool. A keyboard issue needs the action that could not be completed.', 'If the result depends on context the checklist cannot settle, mark it for owner review instead of forcing a pass or fail.']],
    ['Keep legal conclusions out', ['The assistant can organize recurring checks and make patterns visible. They should not claim compliance, noncompliance, or legal risk from one observation.', 'Route uncertain findings to the accessibility or web owner with the exact evidence and the limitation of the check.']],
    ['Make remediation easier to choose', ['Group findings by page and issue type, then preserve the original observations. This helps the owner choose a repair order without losing detail.', 'The review lane is ready to expand when a new page can be checked, evidenced, and routed without inventing a standard.']],
  ],
  'filipino-sales-operations-handoff-coordinator': [
    ['Define a handoff that delivery can use', ['List the customer problem, agreed next step, source notes, owner, and timing that delivery needs. Do not turn a sales conversation into a promise that no one approved.', 'Make missing details visible before the handoff moves. A blank field should create a question, not a guessed answer.']],
    ['Check completeness without qualifying', ['The coordinator can verify that approved fields are present. Sales leadership decides whether an opportunity is qualified or ready for a commercial step.', 'Keep the evidence for commitments, including who said them and when. If a statement has no source, label it for review.']],
    ['Preserve the customer’s language', ['A short account of the customer’s problem should remain traceable to the call note or approved source. Avoid polishing it into a different need.', 'Distinguish the customer’s request from the team’s interpretation. Delivery needs both, with the difference clear.']],
    ['Route risk before transfer', ['Flag unclear scope, timing conflict, missing technical input, and unapproved terms as handoff questions. Send them to the owner who can answer them.', 'Do not resolve a gap by inventing a deadline or changing the stage. The queue records the pause and the reason.']],
    ['Measure handoff rework', ['Review returned handoffs by missing field or unclear commitment. That points to a better intake form or conversation question.', 'Expand only when the receiving team can start from the packet without a private call to reconstruct the deal.']],
  ],
  'filipino-knowledge-article-review-coordinator': [
    ['Inventory the collection before editing', ['Record each article’s owner, review date, source links, audience, and current approval status. Start with an inventory that can be checked independently.', 'An old review date is a flag, not proof that the article is wrong. Keep the approved version available while questions are investigated.']],
    ['Assign review by subject', ['Send technical, policy, or customer-facing articles to the owner who can confirm the answer. A coordinator can schedule the review and collect evidence.', 'Do not silently update an approved answer because a link looks dated or a sentence sounds awkward. Mark the issue and wait for authorization.']],
    ['Preserve versions and decisions', ['Keep the prior copy, proposed change, source, reviewer, and approval date connected. This makes a correction explainable later.', 'A brief decision note should say what changed and why. “Updated” alone does not help the next reviewer.']],
    ['Make stale guidance visible', ['Use labels for overdue, source missing, owner pending, and approved. The labels should describe the state of the record, not judge its quality.', 'If an article affects a customer promise or policy, route it to the responsible owner before publication.']],
    ['Test the reader’s path', ['Ask someone unfamiliar with the article to find the answer and its source. Note where they hesitate, then let the owner decide the content fix.', 'The lane can grow when review status, version history, and approval are visible without opening every article.']],
  ],
  'filipino-operations-calendar-coordinator': [
    ['Start with owners, not reminders', ['Every deadline needs a responsible person, source, time zone, and definition of done. A calendar entry without an owner is only a date.', 'Record dependencies such as an approval or file arrival so a missed predecessor is visible before the deadline passes.']],
    ['Separate a reminder from a decision', ['Sending a reminder does not authorize a priority change, deadline move, or customer message. Keep those decisions with the operations owner.', 'Use a status that says waiting on owner, waiting on dependency, or ready for completion. Avoid a vague “in progress” bucket.']],
    ['Handle time zones explicitly', ['Write the relevant time zone beside deadlines and recurring events. Confirm daylight-saving changes or local holidays through the owner’s approved calendar source.', 'If two calendars conflict, preserve both entries and raise the conflict. Do not choose a “reasonable” time without authority.']],
    ['Make missed work recoverable', ['When a date passes, record the missed dependency, new owner action, and decision needed. Do not move the entry silently and erase the history.', 'A short daily review can focus on today’s blockers rather than producing a long status narrative.']],
    ['Expand by dependency type', ['Add another calendar only after the first one shows reliable ownership and conflict handling. Give new recurring work its own definition of done.', 'The coordinator’s value is early visibility. Priority and tradeoff decisions remain with the operations manager.']],
  ],
  'filipino-customer-case-records-assistant': [
    ['Build a timeline from source records', ['Place contact attempts, attachments, customer statements, and next actions in time order with a source for each entry. Keep the customer’s account distinct from internal interpretation.', 'A clean timeline should show what is known, what is disputed, and what remains unanswered.']],
    ['Use statuses that mean something', ['Choose a small set of statuses tied to an action, such as awaiting customer, owner review, or ready to close. A status should not hide the reason a case is paused.', 'Record the next touch and its owner. Avoid closing a case because the queue is crowded.']],
    ['Protect sensitive case fields', ['Give the role access to the fields needed for the assigned queue and no broader export. Keep sensitive details in the approved system.', 'If a case involves a refund, complaint, or policy exception, preserve the evidence and route it to the decision owner.']],
    ['Resolve duplicate histories carefully', ['When two records describe one issue, compare dates and sources before linking them. Do not delete a customer statement to make the timeline shorter.', 'Flag conflicting contact details for the case owner. The assistant can show the mismatch; the owner decides which record controls.']],
    ['Close with a usable handoff', ['A closing note should state the resolution source, remaining obligation, and person responsible for follow-up. It should not imply a refund or concession that is not approved.', 'Review a sample of closed cases for missing evidence before the lane takes on more categories.']],
  ],
  'filipino-product-data-governance-coordinator': [
    ['Agree on field meanings first', ['Write a short glossary for fields that different teams use differently. Include the authoritative source and the owner of the definition.', 'Do not enforce a definition that has not been approved. A visible disagreement is safer than a quiet bulk correction.']],
    ['Trace changes at field level', ['A change request should identify the field, old value, proposed value, source, requester, and review status. Keep the record narrow enough to audit.', 'Samples can reveal drift without changing every record. Send patterns to the data owner for a decision.']],
    ['Choose an authoritative source', ['When product systems disagree, record which source supplied each value and when it was checked. Never call the newest file authoritative by default.', 'Escalate ownership conflicts with examples that show the practical impact of each choice.']],
    ['Keep governance separate from cleanup', ['The coordinator can run an approved check and prepare a correction request. They should not change a protected field or invent a new validation rule.', 'Mark fields that need a policy decision so a cleanup queue does not become an unapproved governance program.']],
    ['Report drift without drama', ['A useful report shows the field, sample, source mismatch, owner, and next decision. It does not turn a data issue into a claim about team performance.', 'Expand the lane when definitions, sources, and correction authority are clear for the first field group.']],
  ],
  'filipino-recruiting-sourcing-coordinator': [
    ['Start from the approved profile', ['Record the role criteria, location or schedule requirement if supplied by the employer, and must-have evidence before searching. Do not add preferences from guesswork.', 'Keep candidate source, date, and role match notes together so a recruiter can review the path to the shortlist.']],
    ['Separate sourcing from selection', ['The coordinator can search approved channels, remove duplicates, and request missing information. A recruiter or employer decides eligibility and selection.', 'Do not rank a person based on an unstated preference. Label an unanswered criterion and route it as a question.']],
    ['Protect candidate information', ['Use the approved system and minimum necessary fields. Avoid downloading candidate data into personal files or sharing it outside the recruiting group.', 'Record consent or source details when the recruiting process requires them. Escalate access questions before sending a profile onward.']],
    ['Make outreach boundaries explicit', ['Use only approved message copy and sender identity. The coordinator should not promise an interview, role, pay, or outcome.', 'If a candidate asks a question outside the approved response, preserve the question and send it to recruiting.']],
    ['Review source quality fairly', ['Compare channels by complete, traceable records and recruiter feedback, not by a personal impression of candidates. Keep the review about the process.', 'The lane is ready to expand when the approved profile, source log, and data boundaries are understood by a new coordinator.']],
  ],
  'filipino-customer-communications-editor': [
    ['Lock the authorized message', ['Start with the owner’s source copy, audience, channel, and approved commitment. The editing brief should say what cannot change.', 'If the source contains a missing fact or uncertain date, mark it before polishing the prose. Clarity cannot repair an unknown answer.']],
    ['Edit for the reader’s next step', ['Shorten long sentences, define unfamiliar terms, and put the action near the relevant context. Keep the original policy meaning intact.', 'A readable message still needs a reviewer. The editor improves expression, not the business decision behind it.']],
    ['Guard commitments and tone', ['Compare every date, promise, and condition against the source. Do not add reassurance that the owner did not authorize.', 'Flag language that could sound dismissive or absolute, then offer a neutral edit for review rather than sending it.']],
    ['Keep versions easy to compare', ['Save the source, edited draft, owner comment, and final approval together. Use a change note for substantive wording shifts.', 'If the owner changes the underlying fact, reopen the edit instead of treating the old approval as transferable.']],
    ['Use a final factual pass', ['Read the message once for meaning and once for mechanics. Check names, links, dates, and the promised response path against approved material.', 'A small sample of released messages can reveal repeated ambiguity, but only the owner can change the communication standard.']],
  ],
  'filipino-inventory-data-quality-coordinator': [
    ['Choose the source before comparing', ['Write which system or document controls each inventory field and when the comparison runs. Without that choice, a variance is only a disagreement.', 'Keep the two values and their timestamps visible. Do not overwrite one side while investigating.']],
    ['Classify the variance', ['Separate a formatting difference from a quantity, location, or status difference. The category determines who needs to review it.', 'Link the evidence, including the item identifier and source record. A number without context is difficult to correct safely.']],
    ['Escalate high-impact differences', ['A mismatch affecting availability, a customer commitment, or an adjustment request should reach the inventory owner promptly.', 'The coordinator prepares the comparison and the correction request. They do not change stock records or authorize an adjustment.']],
    ['Keep the review reproducible', ['Record comparison time, filters, and any excluded records. Another reviewer should be able to understand how the variance appeared.', 'When a correction is approved, retain the before value, decision owner, and resulting record reference.']],
    ['Look for repeat causes', ['Group variances by field and source so the owner can see whether the issue comes from timing, naming, or a broken handoff.', 'Expand the work only after the first comparison can distinguish a real discrepancy from a harmless representation difference.']],
  ],
  'filipino-service-level-reporting-assistant': [
    ['Define the measurement window', ['Write the reporting period, included queues, timestamp rule, and exclusions before collecting figures. A result changes when those boundaries change.', 'Keep the input records or approved extracts with the report so a reviewer can trace a number back to its source.']],
    ['Name what the metric means', ['Response time, resolution time, and customer wait time are not interchangeable. Put the definition next to the value rather than assuming the reader knows it.', 'If a record lacks a usable timestamp, count it as missing and explain the limitation. Do not silently drop an inconvenient case.']],
    ['Separate reporting from performance action', ['The assistant assembles evidence and notes variance. The service owner decides whether a trend needs staffing, training, or a policy response.', 'Avoid writing a causal explanation when the report only shows a count. Ask the owner for interpretation.']],
    ['Explain exclusions plainly', ['List maintenance windows, paused cases, and incomplete records with the rule used to handle them. A short exclusions note builds trust in the report.', 'Keep revised calculations linked to the original version and reason for change.']],
    ['Make the report reviewable', ['Include the period, definitions, source links, missing-data note, and reviewer field on every report. This is more useful than a polished chart without context.', 'The lane can grow when a second person can rebuild a sample figure and understand why it is included.']],
  ],
  'filipino-privacy-aware-file-coordinator': [
    ['Map access before moving files', ['List the approved location, owner, permitted users, and transfer reason for each file group. Do not create a convenience copy before checking the destination.', 'Use named access and record permission changes. A folder that everyone can open is not a neutral default.']],
    ['Minimize copied material', ['Move only the pages or fields needed for the approved handoff when the process allows it. Keep originals in the controlled source location.', 'If a request needs a full export, document the owner’s authorization and the destination before proceeding.']],
    ['Keep retention questions visible', ['Record the file date, purpose, owner, and retention question without deciding the legal period. A privacy or legal owner should settle uncertain cases.', 'Do not delete a file because it looks old or duplicate. Preserve the question and use the approved disposition route.']],
    ['Log sensitive transfers', ['A transfer note should identify the source, recipient, date, purpose, and approval reference. Keep the note in the approved audit location.', 'Unexpected recipients, rights requests, or disclosure questions should stop the queue and reach the responsible owner.']],
    ['Review exposure, not just filing', ['Sample access lists and copied locations to find unnecessary exposure. Report the exact path and record group rather than making a broad accusation.', 'Expand only when the first file class has clear access, transfer, and escalation rules.']],
  ],
  'filipino-project-risk-register-assistant': [
    ['Write risks as possible events', ['Capture the uncertain event, its cause, affected objective, evidence, owner, and next review date. Keep an actual problem in the issue log instead.', 'Use the project’s approved definitions for likelihood and impact. If the evidence does not support a rating, leave the question for the manager.']],
    ['Keep mitigation tied to an owner', ['A mitigation entry needs an action, responsible person, due date, and evidence of progress. “Monitor” is not enough unless the monitoring method is stated.', 'Do not promise that an action removes the risk. Record what the action is meant to change and what remains uncertain.']],
    ['Separate facts from manager judgment', ['A late dependency is observable; a conclusion about project health belongs to the project manager. Write both only when the source supports them.', 'When team members disagree about a risk, retain the differing evidence and route the question rather than averaging the views.']],
    ['Surface overdue actions', ['Use a dated view of missed mitigation steps and send it to the owner. Do not silently extend a due date or close a risk.', 'A short escalation note should say what is late, what evidence is missing, and which decision is needed.']],
    ['Keep acceptance with leadership', ['The coordinator maintains the register and makes changes traceable. The project manager accepts, transfers, or closes the risk.', 'The lane is ready to expand when the distinction between risk, issue, action, and decision is clear to a new reviewer.']],
  ],
  'filipino-ecommerce-merchandising-coordinator': [
    ['Build a product change packet', ['Collect the approved title, attributes, images, collection, inventory signal, and requested publish time in one reviewable packet.', 'Keep source product facts separate from proposed merchandising language. A missing image is a readiness issue, not a reason to invent a claim.']],
    ['Check fields where customers see them', ['Review the storefront representation against the approved source, including variant names, availability text, and links. Note the exact field that differs.', 'Do not change commercial terms, product claims, or stock status without the merchandising owner.']],
    ['Handle campaign assets carefully', ['Tie each banner, badge, or collection placement to its approved brief and date. Record whether the asset is received, reviewed, or waiting on a decision.', 'If an asset suggests a promotion, route the wording and dates to the authorized commercial owner.']],
    ['Keep inventory and content separate', ['A catalog record can be complete while availability is uncertain. Show the two states separately so a content update does not imply stock.', 'Escalate conflicting inventory sources with their timestamps and item identifiers.']],
    ['Review the publish checklist', ['A final packet should show approvals, source attributes, missing assets, and the person who can release the change. Avoid a generic “ready” label.', 'Expand one collection or change type at a time, and keep a sample of the rendered result for the owner’s review.']],
  ],
  'filipino-finance-reporting-close-coordinator': [
    ['Set the close calendar around evidence', ['List each reporting input, source system, preparer, reviewer, due date, and expected reconciliation. A task is not complete because a file arrived.', 'Keep the period and version on every input. Late changes need a visible note rather than a replacement that erases history.']],
    ['Tie figures to their source', ['A close packet should let the reviewer move from a reported figure to the underlying schedule or approved extract. Record the link and preparation date.', 'If two sources disagree, preserve both and open a question for finance. Do not choose the number that makes the report look cleaner.']],
    ['Track review comments to closure', ['Put each comment beside the figure or schedule it concerns, with an owner and response. Avoid a separate list that loses context.', 'A coordinator can check that a response exists. Finance decides whether the response resolves the issue.']],
    ['Leave adjustments and sign-off alone', ['The role may assemble evidence and flag missing support. It must not post an adjustment, certify a result, or sign for a finance owner.', 'Write the approval boundary in the close instructions so urgency does not change it.']],
    ['Report close readiness honestly', ['Use statuses such as input received, reconciliation pending, reviewer question, and approved. They tell leadership what is actually left.', 'The process is ready to expand when a new coordinator can locate evidence and route an unresolved figure without private coaching.']],
  ],
  'filipino-vendor-onboarding-records-coordinator': [
    ['Separate record completeness from acceptance', ['Create a checklist for supplier forms, required documents, system request, and procurement approval. A full packet does not mean the supplier has been accepted.', 'Keep missing fields and missing decisions in separate statuses so procurement can act on the right problem.']],
    ['Protect tax and banking details', ['Use the approved system and minimum necessary access for sensitive supplier information. Do not send banking data through an informal channel to speed up setup.', 'Record who owns permission changes and route unexpected access requests before sharing a file.']],
    ['Track the source of each document', ['Record received date, document type, supplier reference, and version. If two forms conflict, keep both until procurement decides which one controls.', 'Do not rewrite a supplier’s submitted information to fit a field. Flag the mismatch for review.']],
    ['Make system requests traceable', ['Link the setup request to the approved supplier record and note its status. A system account created without an approval reference should stop.', 'The coordinator can chase a request and report its age. They cannot approve a supplier or bypass a procurement control.']],
    ['Review onboarding by exception', ['Group open packets by missing evidence, conflicting record, and pending approval. That gives procurement a focused queue.', 'Expand after a new supplier record can be checked consistently and sensitive data stays within the approved boundary.']],
  ],
  'filipino-customer-voice-research-coordinator': [
    ['Begin with a clear research question', ['Write what the team wants to learn, who can provide evidence, and which interview or feedback source is approved. A broad theme is not a research question.', 'Keep participant identity and response content in the approved locations, with access limited to the research team.']],
    ['Keep words traceable', ['Save the interview date, question, response excerpt, and source reference before adding a code. Short excerpts should not lose the context that makes them meaningful.', 'If two participants describe similar friction, record the similarity as an observation. The researcher decides whether it is a theme.']],
    ['Separate coding from conclusion', ['A coordinator can apply an approved codebook and show examples. They should not turn a small sample into a claim about every customer.', 'Mark uncertain or overlapping codes and send them to the research owner rather than forcing a tidy category.']],
    ['Protect the participant relationship', ['Use approved scheduling and consent language. Do not promise a product change, response, or incentive beyond the authorized script.', 'Questions about withdrawal, identity, or sensitive content should reach the research or privacy owner promptly.']],
    ['Prepare an evidence pack', ['Give the owner the question, sample description, coded excerpts, gaps, and open interpretation points. Keep raw records available under the approved access rule.', 'The lane is ready to grow when another researcher can trace every reported observation to its source without exposing unnecessary personal data.']],
  ],
  'filipino-workflow-documentation-editor': [
    ['Start from an approved source', ['Collect the current steps, system names, owner corrections, and intended reader before editing. A clean draft is not authority by itself.', 'Mark missing prerequisites and exceptions where the operator will see them. Do not smooth away a step that the owner has not confirmed.']],
    ['Write for the person doing the work', ['Put the action, input, and expected result together. Use the actual field or button name supplied by the owner, and explain what success looks like.', 'If a step depends on judgment, write the question and decision owner instead of hiding it inside a vague verb such as “process.”']],
    ['Use versions as part of the instruction', ['Show document version, owner, effective date, and change note. A worker should be able to tell whether the page is current.', 'Keep the prior approved version available when a change affects a recurring process or customer commitment.']],
    ['Test with a fresh reader', ['Ask someone who did not write the instruction to follow one example and record where they pause. Their questions reveal missing context.', 'Send the test result to the process owner. The editor can improve wording, but the owner approves a new operational rule.']],
    ['Release with a boundary', ['A publish packet should include the approved copy, source owner, version, access location, and review date. Do not publish a draft as if it were final.', 'Expand one adjacent workflow at a time, with its own example and owner sign-off.']],
  ],
} as const;

